import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.BX6FPmO9.js";const m=JSON.parse('{"title":"資料測試導向開發（制度版）","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/data-test-driven.md","filePath":"conventions/data-test-driven.md"}'),n={name:"conventions/data-test-driven.md"};function s(c,t,d,l,h,i){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="資料測試導向開發-制度版" tabindex="-1">資料測試導向開發（制度版） <a class="header-anchor" href="#資料測試導向開發-制度版" aria-label="Permalink to &quot;資料測試導向開發（制度版）&quot;">​</a></h1><p><strong>類型</strong>：spec | <strong>權重</strong>：1</p><p>本文件為<strong>大型協作</strong>下的 Data-Driven Development 制度：可執行、可檢查、可擴張。</p><p><strong>資料治理脈絡</strong>：前端要加速的是「協作效率」與「可治理的資料層」，不是資料格式本身。對等做法為 Contract-first、可執行的 mock（MSW 經 schema parse）、以及 Mock Dataset 版本化（可回溯、可重現）。見 <a href="./../architecture/data-governance.html">data-governance</a>。</p><hr><h2 id="一、流程-spec-→-contract-→-mock-→-test-→-ui" tabindex="-1">一、流程：Spec → Contract → Mock → Test → UI <a class="header-anchor" href="#一、流程-spec-→-contract-→-mock-→-test-→-ui" aria-label="Permalink to &quot;一、流程：Spec → Contract → Mock → Test → UI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步驟</th><th>產出</th><th>負責</th></tr></thead><tbody><tr><td><strong>1. Feature Spec</strong></td><td>業務範圍、資料流、驗收條件（docs/product 或 ticket）</td><td>需求／Tech Lead</td></tr><tr><td><strong>2. Contract</strong></td><td>Schema（Zod）+ API 路徑與方法；request/response 可驗證</td><td>開發者</td></tr><tr><td><strong>3. Mock Layer</strong></td><td>MSW handler，回傳經 schema parse 的資料</td><td>開發者</td></tr><tr><td><strong>4. Test</strong></td><td>單元／整合測試，依 handler 與 fixture 驅動</td><td>開發者</td></tr><tr><td><strong>5. UI Implementation</strong></td><td>元件、hooks、routes；只透過 fetcher 或 shared api 打契約路徑</td><td>開發者</td></tr></tbody></table><p>測試在 UI 實作前即可撰寫（依 Mock 與 Contract）。</p><hr><h2 id="二、強制規則-enforcement" tabindex="-1">二、強制規則（Enforcement） <a class="header-anchor" href="#二、強制規則-enforcement" aria-label="Permalink to &quot;二、強制規則（Enforcement）&quot;">​</a></h2><h3 id="_2-1-schema-必須可驗證" tabindex="-1">2.1 Schema 必須可驗證 <a class="header-anchor" href="#_2-1-schema-必須可驗證" aria-label="Permalink to &quot;2.1 Schema 必須可驗證&quot;">​</a></h3><ul><li>禁止僅依 TypeScript 型別定義契約。</li><li>使用 <strong>Zod</strong> 於 <code>app/shared/contracts/</code> 定義 request/response；handler 與（建議）route 回傳前須通過對應 schema parse。</li><li>見 <a href="./../../specs/api/contract-schema.html">contract-schema</a>。</li></ul><h3 id="_2-2-handler-contract-不是假資料" tabindex="-1">2.2 Handler = Contract，不是假資料 <a class="header-anchor" href="#_2-2-handler-contract-不是假資料" aria-label="Permalink to &quot;2.2 Handler = Contract，不是假資料&quot;">​</a></h3><ul><li>每個對外開放的 API（含 Remix resource route）<strong>必須</strong>在 <code>app/test/handlers.ts</code>（或合併模組）有對應 MSW handler。</li><li>Handler 產出的 response body <strong>必須</strong>經契約 schema parse，不得回傳未驗證物件。</li><li>見 <a href="./../../specs/api/handler-mapping.html">handler-mapping</a>。</li></ul><h3 id="_2-3-api-呼叫必須走約定路徑" tabindex="-1">2.3 API 呼叫必須走約定路徑 <a class="header-anchor" href="#_2-3-api-呼叫必須走約定路徑" aria-label="Permalink to &quot;2.3 API 呼叫必須走約定路徑&quot;">​</a></h3><ul><li><strong>禁止</strong>在 component 內直接 <code>fetch(url)</code> 硬編碼未在契約／對照表中的 URL。</li><li>允許：Remix <code>useFetcher</code> / loader 打契約內定義的 path；或透過 <code>app/shared/api</code> 的 typed client（若有）發送。</li><li>見 <strong>app/shared/api/README.md</strong>。</li></ul><h3 id="_2-4-ci-檢查-建議" tabindex="-1">2.4 CI 檢查（建議） <a class="header-anchor" href="#_2-4-ci-檢查-建議" aria-label="Permalink to &quot;2.4 CI 檢查（建議）&quot;">​</a></h3><ul><li><strong>lint:handlers</strong>：檢查 <code>app/routes/api.*</code> 與 <code>app/test/handlers.ts</code> 的 path 對應，缺 handler 則失敗。</li><li><strong>Test</strong>：MSW 已 listen，未註冊 request 會 onUnhandledRequest: error；新增 API 未補 handler 時測試會失敗。</li><li>未來可加：handler response 的 schema parse 在 test 內斷言。</li></ul><hr><h2 id="三、適用範圍-何時走完整流程" tabindex="-1">三、適用範圍（何時走完整流程） <a class="header-anchor" href="#三、適用範圍-何時走完整流程" aria-label="Permalink to &quot;三、適用範圍（何時走完整流程）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情境</th><th>是否走完整流程</th></tr></thead><tbody><tr><td>新增／變更「對外 API」（resource route、或前端會 fetch 的 endpoint）</td><td><strong>必須</strong>：Spec → Contract → Mock → Test → UI</td></tr><tr><td>僅改 UI 樣式、文案、不碰 API</td><td>不需補 Contract / Mock</td></tr><tr><td>僅改既有 server 內部邏輯、不變 response 形狀</td><td>不需改 Contract；需確認 handler 與 route 仍通過原 schema</td></tr><tr><td>內部工具、一次性 script</td><td>可從簡，不強制 MSW</td></tr></tbody></table><hr><h2 id="四、mock-dataset-版本化-可選-建議大型協作採用" tabindex="-1">四、Mock Dataset 版本化（可選，建議大型協作採用） <a class="header-anchor" href="#四、mock-dataset-版本化-可選-建議大型協作採用" aria-label="Permalink to &quot;四、Mock Dataset 版本化（可選，建議大型協作採用）&quot;">​</a></h2><ul><li>Mock 情境以 <strong>dataset version</strong> 管理（<code>app/test/datasets/v1/</code>、<code>v2/</code>）；schema 或情境變更時新增版本，不直接覆寫舊版。</li><li>每版可含 <code>MIGRATION.md</code> 說明與前一版的差異；測試可指定 version 以重現結果。</li><li>見 <a href="./mock-dataset-versioning.html">mock-dataset-versioning</a>、<a href="./../architecture/data-governance.html">data-governance</a>。</li></ul><hr><h2 id="五、契約漂移-mock-vs-production" tabindex="-1">五、契約漂移（Mock vs Production） <a class="header-anchor" href="#五、契約漂移-mock-vs-production" aria-label="Permalink to &quot;五、契約漂移（Mock vs Production）&quot;">​</a></h2><ul><li><strong>短期</strong>：Zod 為單一來源；handler 與 route 皆用同一 schema parse，減少 mock 與實作不一致。</li><li><strong>中期</strong>：若導入 OpenAPI，可考慮由 OpenAPI 產 Zod 或由 Zod 產 JSON Schema，定期比對或做 contract test（如對 staging 打一輪契約檢查）。</li><li><strong>文件</strong>：<a href="./../../specs/api/handler-mapping.html">handler-mapping</a> 與 <a href="./../../specs/api/contract-schema.html">contract-schema</a> 需隨 API 變更同步更新。</li></ul><hr><h2 id="六、schema-設計能力與-template" tabindex="-1">六、Schema 設計能力與 Template <a class="header-anchor" href="#六、schema-設計能力與-template" aria-label="Permalink to &quot;六、Schema 設計能力與 Template&quot;">​</a></h2><ul><li>新進或對資料建模不熟者：依 <a href="./../../specs/api/contract-schema.html">contract-schema</a> 的 Template 新增契約檔。</li><li>不確定時：先小範圍 schema（單一實體、單一 response），再擴充；避免一次大改導致 UI 不穩。</li></ul><hr><h2 id="七、相關文件" tabindex="-1">七、相關文件 <a class="header-anchor" href="#七、相關文件" aria-label="Permalink to &quot;七、相關文件&quot;">​</a></h2><ul><li><a href="./../../specs/api/contract-schema.html">contract-schema</a>：Zod 使用、契約檔位置、template</li><li><a href="./../../specs/api/handler-mapping.html">handler-mapping</a>：API 清單與 handler 對應</li><li><strong>app/shared/api/README.md</strong>：API 呼叫約定</li><li><strong>.cursor/rules/data-test-driven.mdc</strong>：規則摘要（與本檔同步）</li></ul>',33)])])}const u=e(n,[["render",s]]);export{m as __pageData,u as default};
